func (c *Component) handleQueryLevelNATS(requestCtx context.Context, data []byte) ([]byte, error) {
	if err := c.graphStateContractError("handleQueryLevelNATS"); err != nil {
		return nil, err
	}
	// Create context with timeout for KV operations
	ctx, cancel := context.WithTimeout(requestCtx, 10*time.Second)
	defer cancel()

	// Parse request
	var req LevelRequest
	if err := json.Unmarshal(data, &req); err != nil {
		return nil, errs.WrapInvalid(err, "Component", "handleQueryLevelNATS", "request unmarshal")
	}

	// Apply defaults
	level := req.Level
	if level < 0 {
		level = 0
	}

	// Get communities at level
	communities, err := c.getCommunitiesByLevel(ctx, level)
	if err != nil {
		return nil, err
	}

	response := LevelResponse{
		Level:       level,
		Communities: communities,
		Count:       len(communities),
	}

	return json.Marshal(response)
}

func (f *querySimilarityFinder) FindSimilar(
	ctx context.Context,
	entityID string,
	threshold float64,
	limit int,
) ([]inference.SimilarityResult, error) {
	if f.natsClient == nil {
		return nil, nil
	}

	reqData, err := marshalSimilarRequest(entityID, limit)
	if err != nil {
		return nil, err
	}

	// gh#93 Phase 2: RequestClassified unifies transport + handler errors behind
	// one classified return. Fail-open on any error so the caller
	// (SemanticGapDetector) keeps walking other entities. Most common handler
	// error here is "source entity has no embedding yet" (aggregation/group
	// entities never projected through the embedder).
	respData, err := f.natsClient.RequestClassified(ctx, similarQuerySubject, reqData, similarQueryTimeout)
	if err != nil {
		f.logger.Debug("similarity query failed (transport or handler)",
			slog.String("entity_id", entityID),
			slog.Any("error", err))
		return nil, nil
	}

	results, duration, err := parseSimilarResponse(respData, threshold)
	if err != nil {
		return nil, err
	}

	f.logger.Debug("similarity query complete",
		slog.String("entity_id", entityID),
		slog.Float64("threshold", threshold),
		slog.Int("results", len(results)),
		slog.String("duration", duration))

	return results, nil
}

