func (c *Component) getCommunitiesForDetection(ctx context.Context) ([]inference.CommunityInfo, error) {
	if c.storage == nil {
		return nil, nil
	}

	// Get all communities from storage
	communities, err := c.storage.GetAllCommunities(ctx)
	if err != nil {
		return nil, errs.Wrap(err, "Component", "getCommunitiesForDetection", "get communities")
	}

	if len(communities) == 0 {
		return nil, nil
	}

	// Convert to CommunityInfo
	infos := make([]inference.CommunityInfo, 0, len(communities))
	for _, comm := range communities {
		infos = append(infos, inference.CommunityInfo{
			ID:      comm.ID,
			Members: comm.Members,
			Level:   comm.Level,
		})
	}

	c.logger.Debug("loaded communities for anomaly detection",
		slog.Int("count", len(infos)))

	return infos, nil
}

func (c *Component) handleQueryMembersNATS(requestCtx context.Context, data []byte) ([]byte, error) {
	if err := c.graphStateContractError("handleQueryMembersNATS"); err != nil {
		return nil, err
	}
	// Create context with timeout for KV operations
	ctx, cancel := context.WithTimeout(requestCtx, 10*time.Second)
	defer cancel()

	// Parse request
	var req MembersRequest
	if err := json.Unmarshal(data, &req); err != nil {
		return nil, errs.WrapInvalid(err, "Component", "handleQueryMembersNATS", "request unmarshal")
