type gateDecision struct {
	// proceed reports whether community detection may run this tick.
	proceed bool
	// reason is the typed cause of a defer, and the defer_total label value. Empty
	// (graph.DeferNone) on a proceed.
	reason graph.DeferReason
	// reading is the held readiness state the verdict was reached from.
	reading readiness.Reading
	// ungated marks a proceed that happened ONLY because allow_ungated_reads
	// overrode an unknown status. Such a run has no verified view age, so it must
	// not record a staleness of 0 — that would read as "verified caught up".
	ungated bool
	// semanticActive is the SECOND-axis verdict (B2 §4): whether the semantic-edge
	// tier may apply this cycle — true only when the tier is enabled AND
	// graph-embedding's readiness envelope is healthy. Meaningful only on a proceed
	// and only when semantic edges are enabled; false otherwise (structural-only or
	// n/a). It drives applySemanticGate's per-cycle provider toggle and the
	// semantic_edges_applied signal.
	semanticActive bool
	// embeddingRevision is the COARSE cache-invalidation signal for the semantic
	// tier (B2 §7.1): graph-embedding's IndexedRevision watermark from its held
	// readiness envelope. applySemanticGate hands it to the provider's BeginCycle
	// so a refresh reuses the whole mutual-kNN cache while the watermark is
	// unchanged and rebuilds when it advances. 0 when the tier is disabled or no
	// embedding envelope has been received. Per-entity embedding revision is not
	// cleanly available (the similar-query reply carries none, and reading
	// EMBEDDING_INDEX per entity would add a bucket dependency and N KV gets per
	// cycle), so this index-level watermark is the coarse signal — conservative
	// (it may advance without a semantic-vector change, forcing an unnecessary
	// rebuild) and self-healing, but NOT strictly fresh: IndexedRevision is a
	// low-water-of-pending watermark (graph-embedding/readiness.go), so a single
	// slow in-flight embedding can pin it low while higher revisions complete out
	// of order — during that window a refresh may reuse directed sets one
	// watermark-generation stale. Symmetry is never broken (computeMutual
	// intersects the full committed map), so the residual is a bounded, self-
	// healing stale/missed edge corrected on the next advance. §8 MEASUREMENT
	// CAVEAT: a cycle can score colocation_mean on slightly-stale semantic edges
	// while embedding readiness reports healthy (notably under 8B saturation).
	embeddingRevision uint64
}

type clusteringMetrics struct {
	// stalenessAtDetection is the AGE OF THE VIEW, in milliseconds, that graph-index
	// reported at the moment the most recent community-detection run proceeded. It is
	// THE "report, don't gate" mechanism: readiness withholds a run only for index
	// health, so a lagging view no longer defers anything, and this gauge is the only
	// place the age of the topology behind the published partition surfaces. Stamp the
	// age on the output rather than refusing to produce one. 0 = exactly caught up.
	//
	// It records on EVERY verified run — not, as under the retired max_staleness
	// tolerance, only on the runs a tolerance admitted — so "how stale are our
	// communities" is answerable continuously instead of only while a knob was set.
	//
	// It replaces the ADR-082 index_lag_at_detection gauge, whose unit (revisions)
	// moved 2-4x with coalesce_ms alone and again with write rate, making it
	// uncomparable across two deployments or two loads (gh#590).
	stalenessAtDetection prometheus.Gauge

	// detectionDuration is how long a community-detection run took, in seconds.
	//
	// It exists because a semboids adoption report had to derive this coupling by hand
	// from logs: detection time scales with community SIZE, so as a graph consolidates
	// (many small communities → few large ones) a run can grow several-fold — 4.4s to
	// 23.7s across one observed 90s window. A long run competes with the indexer for
	// the same box, so the view is staler at the next tick.
	//
	// Paired with stalenessAtDetection on a dashboard, the two make that loop visible
	// instead of inferable: rising duration alongside rising staleness is the
	// signature. It is now a pure observation — with no view-age tolerance left, a slow
	// run degrades the FRESHNESS of the published partition rather than stopping
	// clustering outright.
	detectionDuration prometheus.Histogram

	// deferTotal counts deferred detection ticks by typed reason. The label set is
	// CLOSED — it is graph.DeferReason, the same value the structured defer log
	// carries — so an operator can separate a broken index (hard_stop) from a dead
	// status feed (status_unknown), an index still doing its initial build
	// (bootstrap_incomplete), and an envelope this consumer cannot interpret
	// (unrecognized_state) without correlating log lines. Every surviving reason is an
	// INDEX HEALTH fact; none is answered by tuning a tolerance, because there is no
	// longer one to tune. All series are pre-initialized at zero so a reason that has
	// never fired is still scrapeable (absent series break rate() alerting).
	deferTotal *prometheus.CounterVec

	// semanticEdgesApplied is the #618 "is this partition semantically blind?"
	// signal: 1 when the most recent detection cycle ran with the semantic-edge
	// tier ACTIVE (graph-embedding ready, mutual-kNN edges in the vote), 0 when it
	// ran STRUCTURAL-ONLY because the embedding index was not ready. It is the axis
	// that distinguishes "semantics ran and found nothing" (gauge 1, a full cycle
	// with no mutual-kNN pairs) from "semantics never ran" (gauge 0, a cold-index
	// structural-only cycle) — the exact confusion that let a semantically-blind
	// partition commit silently. Only updated on deployments that ENABLE the tier;
	// an unopted deployment never touches it (its value is meaningless there).
	semanticEdgesApplied prometheus.Gauge

	// semanticEdgeBuildMs is the wall-clock duration, in milliseconds, of a single
	// mutual-kNN cache refresh (B2 §7.2). It is observed on every ACTIVE cycle,
	// including the near-zero all-reused cycles: the distribution makes the reuse
	// win visible (a corpus that has not changed refreshes in ~0ms because it
	// issues no similarity queries) and surfaces the O(N)-query rebuild cost when
	// the embedding watermark advances. Only meaningful where enable_semantic_edges
	// is true.
	semanticEdgeBuildMs prometheus.Histogram

	// semanticEdgeSimilarQueries counts the FindSimilar (graph.embedding.query.similar)
	// calls the mutual-kNN refresh issues (B2 §7.2). It is the load the revision-keyed
	// cache (§7.1) bounds: on an unchanged corpus a refresh reuses every directed set
	// and this counter does not move, so increase() over a scrape interval reads ~0;
	// it steps up by the re-queried entity count when the embedding watermark advances
	// or a previously-errored entity is retried. Watching it is how an operator
	// confirms the cache is actually bounding query load rather than re-issuing ~N
	// queries per cycle. Only meaningful where enable_semantic_edges is true.
	semanticEdgeSimilarQueries prometheus.Counter
}

func semanticActiveFromReading(r readiness.Reading) bool {
	proceed, _ := graph.EvaluateReadinessGate(
		graph.StatusReading{Status: r.Status, Fresh: r.Fresh})
	return proceed
}

func (c *Component) wrapSemanticEdges(entityIDProvider *clustering.EntityIDProvider) clustering.Provider {
	finder := c.initQuerySimilarityFinder()
	if finder == nil {
		// No NATS client -> no similarity path. Degrade to structural-only rather
		// than failing Start; the tier is additive over an always-valid floor.
		// c.semanticProvider stays nil, so applySemanticGate is a no-op and the
		// deployment runs permanent structural-only.
		c.logger.Warn("semantic edges enabled but similarity finder unavailable, running structural-only")
		return entityIDProvider
	}
	weights := clustering.WeightConfig{
		SiblingWeight:    c.config.entityIDEdges.SiblingWeight,
		SystemPeerWeight: c.config.entityIDEdges.SystemPeerWeight,
		SemanticWeight:   c.config.semanticEdges.weight,
	}
	provider := clustering.NewSemanticEdgeProvider(
		entityIDProvider,
		semanticFinderAdapter{finder: finder},
		weights,
		clustering.SemanticEdgeParams{
			K:         c.config.semanticEdges.k,
			Threshold: c.config.semanticEdges.threshold,
		},
		c.logger,
	)
	// Wire the §7.2 refresh-cost recorder (build duration + query count) when the
	// component holds a metrics registry; nil-safe otherwise (unit-test wiring).
	if c.metrics != nil {
		provider.WithMetrics(semanticEdgeMetricsAdapter{m: c.metrics})
	}
	c.semanticProvider = provider
	return provider
}

func (c *Component) handleQueryCommunityNATS(requestCtx context.Context, data []byte) ([]byte, error) {
	if err := c.graphStateContractError("handleQueryCommunityNATS"); err != nil {
		return nil, err
	}
	// Create context with timeout for KV operations
	ctx, cancel := context.WithTimeout(requestCtx, 10*time.Second)
	defer cancel()

	// Parse request
	var req CommunityRequest
	if err := json.Unmarshal(data, &req); err != nil {
		return nil, errs.WrapInvalid(err, "Component", "handleQueryCommunityNATS", "request unmarshal")
	}

	// Validate request
	if req.ID == "" {
		return nil, errs.WrapInvalid(errs.ErrInvalidConfig, "Component", "handleQueryCommunityNATS", "empty community id")
	}

	// Get community from bucket
	community, err := c.getCommunity(ctx, req.ID)
	if err != nil {
		return nil, err
	}

	response := CommunityResponse{
		Community: community,
	}

	return json.Marshal(response)
}

