func (c *Component) getCommunitiesByLevel(ctx context.Context, level int) ([]*clustering.Community, error) {
	if c.communityBucket == nil {
		return nil, errs.WrapFatal(errs.ErrInvalidConfig, "Component", "getCommunitiesByLevel", "community bucket not initialized")
	}

	// Use server-side prefix filtering: community keys are "{level}.{id}"
	pattern := fmt.Sprintf("%d.>", level)
	keys, err := natsclient.FilteredKeys(ctx, c.communityBucket, pattern)
	if err != nil {
		return nil, errs.WrapTransient(err, "Component", "getCommunitiesByLevel", "list keys")
	}

	var communities []*clustering.Community

	for _, key := range keys {
		entry, err := c.communityBucket.Get(ctx, key)
		if err != nil {
			// A key can disappear between the filtered listing and the point read.
			// That proven not-found race is safe to omit; every other failure means
			// the scan is incomplete and must not be returned as authoritative.
			if errors.Is(err, jetstream.ErrKeyNotFound) {
				continue
			}
			return nil, errs.WrapTransient(err, "Component", "getCommunitiesByLevel", "get community")
		}

		var community clustering.Community
		if err := json.Unmarshal(entry.Value(), &community); err != nil {
			return nil, errs.WrapInvalid(err, "Component", "getCommunitiesByLevel", "community unmarshal")
		}

		communities = append(communities, &community)
	}

	return communities, nil
}

func (c *Component) startStatusWatcher(ctx context.Context) error {
	heartbeat := c.statusHeartbeat
	if heartbeat <= 0 {
		heartbeat = readiness.DefaultHeartbeat
	}
	watcher := readiness.NewWatcher(c.natsClient, readiness.KeyGraphIndex,
		readiness.WithHeartbeat(heartbeat),
		readiness.WithLogger(c.logger))
	if err := watcher.Start(ctx); err != nil {
		return fmt.Errorf("start readiness watcher on %s/%s: %w",
			readiness.BucketGraphStatus, readiness.KeyGraphIndex, err)
	}
	c.statusWatcher = watcher

	// Second readiness axis (B2 §4.1): graph-embedding's status key, bound ONLY
	// when the semantic-edge tier is enabled so an unopted deployment starts no
	// wasted subscription. A cold embedding index does not defer the cycle — it
	// drops the cycle to structural-only — so an absent/unknown feed here is
	// benign, exactly like the index watcher's absent case.
	if c.config.semanticEdges.enabled {
		embWatcher := readiness.NewWatcher(c.natsClient, readiness.KeyGraphEmbedding,
			readiness.WithHeartbeat(heartbeat),
			readiness.WithLogger(c.logger))
		if err := embWatcher.Start(ctx); err != nil {
			return fmt.Errorf("start readiness watcher on %s/%s: %w",
				readiness.BucketGraphStatus, readiness.KeyGraphEmbedding, err)
		}
		c.embeddingStatusWatcher = embWatcher
	}
	return nil
}

func (m *clusteringMetrics) registerSemanticMetrics(registry *metric.MetricsRegistry) {
	if m == nil || m.semanticEdgesApplied == nil {
		return
	}
	if registry != nil {
		_ = registry.RegisterGauge("graph-clustering", "semantic_edges_applied", m.semanticEdgesApplied)
		_ = registry.RegisterHistogram("graph-clustering", "semantic_edge_build_ms", m.semanticEdgeBuildMs)
		_ = registry.RegisterCounter("graph-clustering", "semantic_edge_similar_queries_total", m.semanticEdgeSimilarQueries)
		return
	}
	_ = prometheus.DefaultRegisterer.Register(m.semanticEdgesApplied)
	_ = prometheus.DefaultRegisterer.Register(m.semanticEdgeBuildMs)
	_ = prometheus.DefaultRegisterer.Register(m.semanticEdgeSimilarQueries)
}

func (c *Component) Stop(ctx context.Context) error {
	if ctx == nil {
		return errs.WrapInvalid(errs.ErrInvalidData, "LifecycleComponent", "Stop", "nil context")
	}
	for {
		c.lifecycleMu.Lock()
		if !c.lifecycleUsed {
			c.lifecycleUsed = true
			c.lifecycleTerminal = true
			c.lifecycleMu.Unlock()
			return nil
		}
		if c.lifecycleTerminal {
			c.lifecycleMu.Unlock()
			return nil
		}
		startDone := c.startDone
		if startDone != nil {
			c.lifecycleMu.Unlock()
			select {
			case <-startDone:
				continue
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		if c.stopping {
			c.lifecycleMu.Unlock()
			return errs.WrapTransient(errors.New("stop already in progress"), "Component", "Stop", "concurrent Stop is unsupported")
		}
		retryable := c.cleanupPending
		c.stopping = true
		c.lifecycleMu.Unlock()

		stopErr := c.cleanup(ctx, retryable)
		c.lifecycleMu.Lock()
		c.stopping = false
		if retryable && stopErr != nil {
			c.lifecycleMu.Unlock()
			return stopErr
		}
		c.cleanupPending = false
		c.lifecycleTerminal = true
		c.clearLifecycleHandles()
		c.lifecycleMu.Unlock()
		c.mu.Lock()
		c.running = false
		c.mu.Unlock()
		c.logger.Info("component stopped gracefully", slog.String("component", "graph-clustering"))
		return stopErr
	}
}

