func (c *Component) handleQueryEntityNATS(requestCtx context.Context, data []byte) ([]byte, error) {
	if err := c.graphStateContractError("handleQueryEntityNATS"); err != nil {
		return nil, err
	}
	// Create context with timeout for KV operations
	ctx, cancel := context.WithTimeout(requestCtx, 10*time.Second)
	defer cancel()

	// Parse request
	var req EntityRequest
	if err := json.Unmarshal(data, &req); err != nil {
		return nil, errs.WrapInvalid(err, "Component", "handleQueryEntityNATS", "request unmarshal")
	}

	// Validate request
	if req.EntityID == "" {
		return nil, errs.WrapInvalid(errs.ErrInvalidConfig, "Component", "handleQueryEntityNATS", "empty entity id")
	}

	// Apply defaults
	level := req.Level
	if level < 0 {
		level = 0
	}

	// Get entity community by scanning communities at level
	community, err := c.getEntityCommunity(ctx, req.EntityID, level)
	if err != nil {
		return nil, err
	}

	response := EntityResponse{
		EntityID:  req.EntityID,
		Level:     level,
		Community: community,
	}

	return json.Marshal(response)
}

func (c *Component) initAnomalyDetection(ctx context.Context) error {
	// ANOMALY_INDEX bucket (we are the WRITER) — acquired through the catalog
	// owner seam.
	anomalyBucket, err := graph.EnsureCatalogBucket(ctx, c.natsClient, graph.BucketAnomalyIndex)
	if err != nil {
		if ctx.Err() != nil {
			return errs.Wrap(ctx.Err(), "Component", "initAnomalyDetection", "context cancelled during bucket creation")
		}
		return errs.Wrap(err, "Component", "initAnomalyDetection", "create ANOMALY_INDEX bucket")
	}
	c.anomalyBucket = anomalyBucket

	// Create anomaly storage
	anomalyStorage := inference.NewNATSAnomalyStorage(anomalyBucket, c.logger)
	c.anomalyStorage = anomalyStorage

	// Create orchestrator
	orchestrator, err := inference.NewOrchestrator(inference.OrchestratorConfig{
		Config:  c.config.AnomalyConfig,
		Storage: anomalyStorage,
		Logger:  c.logger,
	})
	if err != nil {
		return errs.Wrap(err, "Component", "initAnomalyDetection", "create orchestrator")
	}
	c.anomalyOrchestrator = orchestrator

	// Set up relationship applier for auto-apply if enabled
	if c.config.AnomalyConfig.VirtualEdges.AutoApply.Enabled {
		if err := c.setupRelationshipApplier(); err != nil {
			c.logger.Warn("failed to set up relationship applier, virtual edges will not auto-apply",
				slog.Any("error", err))
		}
	}

	// Register enabled detectors
	if err := c.registerAnomalyDetectors(); err != nil {
		return errs.Wrap(err, "Component", "initAnomalyDetection", "register detectors")
	}

	// Initialize similarity finder for semantic gap detection (optional)
	// Uses query path to graph-embedding instead of direct KV access
	if c.config.AnomalyConfig.SemanticGap.Enabled {
		finder := c.initQuerySimilarityFinder()
		if finder != nil {
			c.similarityFinder = finder
		}
	}

	c.logger.Info("anomaly detection initialized",
		slog.Any("enabled_detectors", c.config.AnomalyConfig.GetEnabledDetectors()),
		slog.Int("max_anomalies_per_run", c.config.AnomalyConfig.MaxAnomaliesPerRun),
		slog.Bool("similarity_finder_available", c.similarityFinder != nil))

	return nil
}

func (e *EntityIDEdgesConfig) resolveOver(baseline clustering.EntityIDProviderConfig) clustering.EntityIDProviderConfig {
	cfg := baseline
	if e == nil {
		return cfg
	}
	if e.IncludeSiblings != nil {
		cfg.IncludeSiblings = *e.IncludeSiblings
	}
	if e.IncludeSystemPeers != nil {
		cfg.IncludeSystemPeers = *e.IncludeSystemPeers
	}
	if e.SiblingWeight > 0 {
		cfg.SiblingWeight = e.SiblingWeight
	}
	if e.MaxSiblings > 0 {
		cfg.MaxSiblings = e.MaxSiblings
	}
	if e.SystemPeerWeight > 0 {
		cfg.SystemPeerWeight = e.SystemPeerWeight
	}
	if e.MaxSystemPeers > 0 {
		cfg.MaxSystemPeers = e.MaxSystemPeers
	}
	return cfg
}

func (c *Config) ApplyDefaults() {
	// Parse detection interval from string
	if c.DetectionIntervalStr != "" {
		if d, err := time.ParseDuration(c.DetectionIntervalStr); err == nil {
			c.detectionInterval = d
		}
	}
	if c.detectionInterval == 0 {
		c.detectionInterval = 30 * time.Second
	}

	if c.BatchSize == 0 {
		c.BatchSize = 100
	}
	// EnableLLM defaults to false (zero value)
	if c.MinCommunitySize == 0 {
		c.MinCommunitySize = 3
	}
	if c.MaxIterations == 0 {
		c.MaxIterations = 100
	}
	if c.EnhancementWorkers == 0 {
		c.EnhancementWorkers = 5 // Increased from default 3 for better parallelism
	}
	// Anomaly detection defaults
	if c.EnableAnomalyDetection {
		c.AnomalyConfig.ApplyDefaults()
	}

	// Dependency startup defaults
	if c.StartupAttempts == 0 {
		c.StartupAttempts = 30 // ~15 seconds with 500ms interval
	}
	if c.StartupInterval == 0 {
		c.StartupInterval = 500 // milliseconds
	}

	// Resolve semantic co-location virtual-edge synthesis (Epic B B2, ADR-086).
	// Nil SemanticEdges resolves to enabled=false — omitting the block keeps the
	// tier OFF and the detection chain unchanged.
	c.semanticEdges = c.SemanticEdges.resolve()

	// Resolve EntityID virtual-edge synthesis (gh#461). Nil EntityIDEdges
	// resolves to the built-in defaults (synthesis ON) — omitting the block
	// preserves current behavior. When the semantic tier is enabled, resolve over
	// the rebalanced structural baseline instead (operator overrides still win);
	// when disabled, this is the exact same call as before — byte-identical.
	if c.semanticEdges.enabled {
		c.entityIDEdges = c.EntityIDEdges.resolveOver(semanticEnabledEntityIDBaseline())
	} else {
		c.entityIDEdges = c.EntityIDEdges.resolve()
	}

	// Add optional output ports based on enabled features
	if c.Ports != nil {
		// Add ANOMALY_INDEX output when anomaly detection is enabled
		if c.EnableAnomalyDetection {
			hasAnomaly := false
			for _, o := range c.Ports.Outputs {
				resolved, err := o.Resolve(component.DirectionOutput)
				if err != nil {
					continue
				}
				facts, err := resolved.Facts()
				if err == nil && facts.ResourceID() == "kv:"+graph.BucketAnomalyIndex {
					hasAnomaly = true
					break
				}
			}
			if !hasAnomaly {
				c.Ports.Outputs = append(c.Ports.Outputs, component.PortDefinition{
					Name: "anomaly_index", Config: component.KVWritePort{Bucket: graph.BucketAnomalyIndex},
				})
			}
		}
	}

	if c.Ports == nil {
		// Apply full default port config
		defaultConf := DefaultConfig()
		c.Ports = defaultConf.Ports
	} else {
		// If ports exist but are empty, populate with defaults
		if len(c.Ports.Inputs) == 0 {
			c.Ports.Inputs = []component.PortDefinition{
				{
					Name: "entity_watch", Config: component.KVWatchPort{Bucket: graph.BucketEntityStates},
				},
			}
		}
		if len(c.Ports.Outputs) == 0 {
			c.Ports.Outputs = []component.PortDefinition{
				{
					Name: "graph_mutations", Config: component.NATSRequestPort{Subject: graphmutation.SubjectFamily, Interface: &component.InterfaceContract{Type: graphmutation.InterfaceType, Version: graphmutation.InterfaceVersion}}, Required: true,
				},
				{
					Name: "communities", Config: component.KVWritePort{Bucket: graph.BucketCommunityIndex},
				},
			}
		}
	}
}

func (p *kvProvider) computeBothNeighborSet(ctx context.Context, entityID string) (map[string]bool, error) {
	neighbors := make(map[string]bool)

	outgoing, err := p.getNeighborsFromBucket(ctx, p.outgoingBucket, entityID)
	if err != nil {
		return nil, errs.WrapTransient(err, "kvProvider", "computeBothNeighborSet", "outgoing topology read")
	}
	for _, n := range outgoing {
		neighbors[n] = true
	}

	incoming, err := p.getIncomingNeighbors(ctx, entityID)
	if err != nil {
		return nil, errs.WrapTransient(err, "kvProvider", "computeBothNeighborSet", "incoming topology read")
	}
	for _, n := range incoming {
		neighbors[n] = true
	}

	return neighbors, nil
}

