func (c *Component) applySemanticGate(d gateDecision) {
	if !c.config.semanticEdges.enabled || c.semanticProvider == nil {
		return
	}
	// One synchronized per-cycle transition (B2 §7.1, Codex P2#4): BeginCycle records
	// the coarse embedding-index watermark, sets the tier active/inactive from the
	// readiness verdict, resets the per-cycle abort/degrade latches, and advances the
	// refresh epoch LAST — atomically, so a concurrent B3 enhancement-worker reader can
	// never observe the new epoch under the prior cycle's active verdict or a stale
	// abort latch. The cycle's first refresh then reuses the whole mutual-kNN cache
	// when the watermark is unchanged and rebuilds only when it advances; harmless on a
	// structural-only cycle (the deactivated provider never refreshes), and it keeps
	// the watermark current for the next active cycle. Formerly two calls
	// (BeginCycle-then-SetActive), which left a torn-state window between them.
	c.semanticProvider.BeginCycle(d.embeddingRevision, d.semanticActive)
}

func (p *kvProvider) GetAllEntityIDs(ctx context.Context) ([]string, error) {
	keys, err := p.entityBucket.Keys(ctx)
	if err != nil {
		// Empty bucket returns an error in some cases
		if err == jetstream.ErrNoKeysFound {
			return nil, nil
		}
		return nil, errs.WrapTransient(err, "kvProvider", "GetAllEntityIDs", "list keys")
	}
	return keys, nil
}

func rejectUnknownSemanticEdgeKeys(raw json.RawMessage) error {
	if len(raw) == 0 {
		return nil
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var probe SemanticEdgesConfig
	if err := dec.Decode(&probe); err != nil {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "graphclustering", "rejectUnknownSemanticEdgeKeys",
			fmt.Sprintf("semantic_edges has a key that does not bind and would be silently ignored at runtime (ADR-086/ADR-054): %v", err))
	}
	return nil
}

func (c *Component) Health() component.HealthStatus {
	c.mu.RLock()
	defer c.mu.RUnlock()

	uptime := time.Duration(0)
	if c.running && !c.startTime.IsZero() {
		uptime = time.Since(c.startTime)
	}

	errorCount := int(atomic.LoadInt64(&c.errors))
	lastErr := ""
	status := "stopped"

	if c.running {
		status = "running"
		if c.graphStatePoison.Load() != nil {
			status = graph.IndexStateResetRequired
			lastErr = graph.ErrorCodeGraphStateResetRequired
		}
		if errorCount > 0 {
			lastErr = "errors occurred during processing"
		}
	}

	return component.HealthStatus{
		Healthy:    c.running && errorCount == 0 && c.graphStatePoison.Load() == nil,
		LastCheck:  time.Now(),
		ErrorCount: errorCount,
		LastError:  lastErr,
		Uptime:     uptime,
		Status:     status,
	}
}

