func (c *Component) setupQueryHandlers(ctx context.Context) error {
	subscribe := c.subscribeForRequests
	if subscribe == nil {
		subscribe = c.natsClient.SubscribeForRequests
	}
	// Subscribe to community query
	sub1, err := subscribe(ctx, "graph.clustering.query.community", c.handleQueryCommunityNATS)
	if err != nil {
		return errs.WrapTransient(err, "Component", "setupQueryHandlers", "subscribe community query")
	}
	c.querySubscriptions = append(c.querySubscriptions, sub1)

	// Subscribe to members query
	sub2, err := subscribe(ctx, "graph.clustering.query.members", c.handleQueryMembersNATS)
	if err != nil {
		return errs.WrapTransient(err, "Component", "setupQueryHandlers", "subscribe members query")
	}
	c.querySubscriptions = append(c.querySubscriptions, sub2)

	// Subscribe to entity community query
	sub3, err := subscribe(ctx, "graph.clustering.query.entity", c.handleQueryEntityNATS)
	if err != nil {
		return errs.WrapTransient(err, "Component", "setupQueryHandlers", "subscribe entity query")
	}
	c.querySubscriptions = append(c.querySubscriptions, sub3)

	// Subscribe to level query
	sub4, err := subscribe(ctx, "graph.clustering.query.level", c.handleQueryLevelNATS)
	if err != nil {
		return errs.WrapTransient(err, "Component", "setupQueryHandlers", "subscribe level query")
	}
	c.querySubscriptions = append(c.querySubscriptions, sub4)

	c.logger.Info("query handlers registered",
		"subjects", []string{
			"graph.clustering.query.community",
			"graph.clustering.query.members",
			"graph.clustering.query.entity",
			"graph.clustering.query.level",
		})

	return nil
}

func getMetrics(registry *metric.MetricsRegistry) *clusteringMetrics {
	metricsOnce.Do(func() {
		metrics = &clusteringMetrics{
			stalenessAtDetection: prometheus.NewGauge(prometheus.GaugeOpts{
				Namespace: "semstreams",
				Subsystem: "graph_clustering",
				Name:      "staleness_at_detection_ms",
				Help:      "Age of the graph-index view, in milliseconds, when the last community detection run proceeded (0 = exactly caught up). Recorded on every verified run: readiness gates on index health alone, so a lagging view never withholds a run and this gauge is where that lag is reported instead.",
			}),
			detectionDuration: prometheus.NewHistogram(prometheus.HistogramOpts{
				Namespace: "semstreams",
				Subsystem: "graph_clustering",
				Name:      "detection_duration_seconds",
				Help:      "Wall time of a community-detection run. Scales with community size, so it grows as a graph consolidates; a long run competes with the indexer for the same box, so watch it alongside staleness_at_detection_ms — rising together means the published partition is getting older, not that clustering is being withheld.",
				// Detection observed between ~4s and ~24s on a 200-entity flock; the
				// buckets bracket that with room either side rather than using the
				// default second-scale set, which would pile everything into +Inf.
				Buckets: []float64{0.5, 1, 2, 5, 10, 20, 30, 60, 120},
			}),
			deferTotal: prometheus.NewCounterVec(prometheus.CounterOpts{
				Namespace: "semstreams",
				Subsystem: "graph_clustering",
				Name:      "defer_total",
				Help:      "Community detection ticks deferred by the readiness gate, by reason: hard_stop (degraded/reset_required index), status_unknown (no fresh readiness envelope — the feed died or graph-index is absent), bootstrap_incomplete (producer has not finished its initial build this process lifetime), unrecognized_state (envelope State is blank or outside the known set — version skew). All four are index-health faults; a merely lagging view is never deferred — its age is reported on staleness_at_detection_ms.",
			}, []string{"reason"}),
			semanticEdgesApplied: prometheus.NewGauge(prometheus.GaugeOpts{
				Namespace: "semstreams",
				Subsystem: "graph_clustering",
				Name:      "semantic_edges_applied",
				Help:      "Whether the most recent community-detection cycle applied the semantic-edge tier: 1 = active (graph-embedding ready, mutual-kNN edges in the vote), 0 = structural-only (embedding index not ready). Distinguishes a full cycle that found no mutual-kNN neighbors (1) from a semantically-blind cycle that never ran semantics (0) — the #618 signal. Only meaningful where enable_semantic_edges is true.",
			}),
			semanticEdgeBuildMs: prometheus.NewHistogram(prometheus.HistogramOpts{
				Namespace: "semstreams",
				Subsystem: "graph_clustering",
				Name:      "semantic_edge_build_ms",
				Help:      "Wall time of one mutual-kNN cache refresh, in milliseconds (B2 §7). Observed every active cycle: an unchanged corpus refreshes in ~0ms (it reuses every cached directed set and issues no similarity queries), while an embedding-watermark advance triggers an O(N)-query rebuild. Read alongside semantic_edge_similar_queries_total to see the revision-keyed cache bounding query load. Only meaningful where enable_semantic_edges is true.",
				// A reuse cycle is sub-millisecond; a full rebuild spans one query per
				// entity, each up to the 30s similarity timeout. Bracket both ends.
				Buckets: []float64{0.1, 0.5, 1, 5, 10, 50, 100, 500, 1000, 5000, 30000},
			}),
			semanticEdgeSimilarQueries: prometheus.NewCounter(prometheus.CounterOpts{
				Namespace: "semstreams",
				Subsystem: "graph_clustering",
				Name:      "semantic_edge_similar_queries_total",
				Help:      "FindSimilar (graph.embedding.query.similar) calls issued by the mutual-kNN cache refresh (B2 §7). The revision-keyed cache (§7.1) bounds this: on an unchanged corpus a refresh reuses every directed set and this counter does not advance, so increase() over a scrape interval reads ~0; it steps up by the re-queried entity count when the embedding watermark advances or an errored entity is retried. Only meaningful where enable_semantic_edges is true.",
			}),
		}
		for _, reason := range deferReasons {
			metrics.deferTotal.WithLabelValues(string(reason))
		}
		// The THREE semantic-tier series (semanticEdgesApplied, semanticEdgeBuildMs,
		// semanticEdgeSimilarQueries) are created above (so the fields are never nil and
		// stamping never panics) but are deliberately NOT registered here: they are
		// exposed ONLY for a deployment that ENABLES the tier, via registerSemanticMetrics
		// called from the factory. Registering them unconditionally would change the
		// exported metric surface of a DISABLED (default-off) deployment — a registered
		// semantic_edges_applied scrapes a default 0 indistinguishable from an
		// enabled-but-cold cycle (#618), and the §7 refresh-cost series appear on a
		// deployment that never runs a refresh — contradicting default-off-identical
		// (Codex P2#4/P2#5).
		if registry != nil {
			_ = registry.RegisterGauge("graph-clustering", "staleness_at_detection_ms", metrics.stalenessAtDetection)
			_ = registry.RegisterCounterVec("graph-clustering", "defer_total", metrics.deferTotal)
			_ = registry.RegisterHistogram("graph-clustering", "detection_duration_seconds", metrics.detectionDuration)
		} else {
			_ = prometheus.DefaultRegisterer.Register(metrics.stalenessAtDetection)
			_ = prometheus.DefaultRegisterer.Register(metrics.deferTotal)
			_ = prometheus.DefaultRegisterer.Register(metrics.detectionDuration)
		}
	})
	return metrics
}

type Component struct {
	// Component metadata
	name    string
	config  Config
	inputs  []component.Port
	outputs []component.Port

	// Dependencies
	natsClient      *natsclient.Client
	logger          *slog.Logger
	modelRegistry   model.RegistryReader
	metricsRegistry *metric.MetricsRegistry // retained to wire summary-worker metrics

	// Domain resources
	communityBucket jetstream.KeyValue
	summaryBucket   jetstream.KeyValue // COMMUNITY_SUMMARIES — worker-owned summary store
	entityBucket    entityBucketReader
	outgoingBucket  outgoingBucketReader
	incomingBucket  incomingBucketReader

	// Community detection
	detector clustering.CommunityDetector
	storage  *clustering.NATSCommunityStorage

	// Ephemeral structural analysis for anomaly detection. graphProvider is the
	// explicit plus EntityID-derived provider, deliberately excluding semantic
	// virtual edges; previousKCore supports same-process demotion detection.
	graphProvider clustering.Provider
	previousKCore *structural.KCoreIndex

	// Anomaly detection (optional; structural prerequisites are ephemeral)
	anomalyBucket       jetstream.KeyValue
	anomalyStorage      inference.Storage
	anomalyOrchestrator *inference.Orchestrator
	similarityFinder    inference.SimilarityFinder // for semantic gap detection

	// LLM enhancement (optional)
	enhancementWorker *clustering.EnhancementWorker
	llmClient         llm.Client

	// Review worker (optional, for anomaly approval workflow). The review
	// worker may use a dedicated LLM client when the operator binds
	// model.CapabilityAnomalyReview to a different endpoint than
	// community_summary; otherwise it shares llmClient.
	reviewWorker    *inference.ReviewWorker
	reviewLLMClient llm.Client // non-nil only when distinct from llmClient

	// Readiness gate (ADR-083 §3). statusWatcher holds graph-index's last-known
	// ADR-066 envelope from the GRAPH_STATUS KV bucket, so a detection tick decides
	// against held state instead of a per-tick request/reply that dies under exactly
	// the load that makes readiness interesting (gh#590). It is constructed during
	// the owner's sole Start because a stopped Watcher cannot be restarted.
	statusWatcher *readiness.Watcher
	// embeddingStatusWatcher holds graph-embedding's last-known readiness envelope
	// from the SAME GRAPH_STATUS bucket (KeyGraphEmbedding), and is bound ONLY when
	// enable_semantic_edges is true — the second axis of the detection gate
	// (B2 §4). It never DEFERS a cycle: a cold embedding index degrades the cycle
	// to structural-only (semantic_edges_applied=false), it never withholds the
	// always-committing structural floor. Constructed during the owner's sole Start.
	embeddingStatusWatcher *readiness.Watcher
	// statusHeartbeat declares the producer's publish interval, which sets the
	// freshness window (readiness.FreshnessMultiplier x heartbeat). Zero means
	// readiness.DefaultHeartbeat. Unexported and not an operator knob (ADR-083 D2
	// keeps the multiplier constant); tests shorten it so a feed-dies assertion
	// costs milliseconds rather than three real heartbeats.
	statusHeartbeat time.Duration
	// lastDeferReason is the previous tick's gate outcome, used to log a VISIBLE
	// line on every transition without emitting one per tick forever. Guarded by
	// deferMu because Stop may race the detection goroutine's final tick.
	deferMu         sync.Mutex
	lastDeferReason graph.DeferReason
	// semanticProvider is the concrete SemanticEdgeProvider handle (also the top of
	// the community detector's provider chain) when enable_semantic_edges is true,
	// nil otherwise. It
	// is held typed so applySemanticGate can toggle it per cycle from embedding
	// readiness. Set under c.mu in initProviderAndDetector before the detection
	// goroutine launches, then only read/toggled by that goroutine (B3's enhancement
	// worker becomes a second reader; the toggle is atomic).
	semanticProvider *clustering.SemanticEdgeProvider
	// lastSemanticApplied tracks the previous cycle's semantic-tier verdict so a
	// structural-only <-> full TRANSITION logs one visible line rather than silence
	// or a per-tick flood. nil = no cycle observed yet. Guarded by semanticMu.
	semanticMu          sync.Mutex
	lastSemanticApplied *bool

	// Lifecycle state
	mu                sync.RWMutex
	lifecycleMu       sync.Mutex
	running           bool
	initialized       bool
	startTime         time.Time
	wg                sync.WaitGroup
	lifecycleUsed     bool
	cleanupPending    bool
	lifecycleTerminal bool
	stopping          bool
	startDone         chan struct{}
	cancel            context.CancelFunc
	runtimeDone       chan struct{}

	// Metrics (atomic)
	messagesProcessed int64
	bytesProcessed    int64
	errors            int64
	lastActivity      atomic.Value // stores time.Time
	graphStatePoison  atomic.Pointer[graph.StateContractError]
	metrics           *clusteringMetrics

	// Query subscriptions (for cleanup)
	querySubscriptions   []*natsclient.Subscription
	subscribeForRequests func(context.Context, string, func(context.Context, []byte) ([]byte, error)) (*natsclient.Subscription, error)
}

func (m *clusteringMetrics) setSemanticEdgesApplied(active bool) {
	if active {
		m.semanticEdgesApplied.Set(1)
		return
	}
	m.semanticEdgesApplied.Set(0)
}

