func DeclarePorts(rawConfig json.RawMessage, _ string) (component.PortConfig, error) {
	_, inputs, outputs, err := resolveConfig(rawConfig)
	if err != nil {
		return component.PortConfig{}, err
	}
	return component.PortConfigFrom(inputs, outputs), nil
}

func (c *Component) noteSemanticApplied(active bool) {
	c.semanticMu.Lock()
	changed := c.lastSemanticApplied == nil || *c.lastSemanticApplied != active
	v := active
	c.lastSemanticApplied = &v
	c.semanticMu.Unlock()
	if !changed {
		return
	}
	if active {
		c.logger.Info("semantic-edge tier active; community detection includes mutual-kNN semantic edges",
			slog.Bool("semantic_edges_applied", true))
		return
	}
	c.logger.Warn("semantic-edge tier INACTIVE; running STRUCTURAL-ONLY this cycle — graph-embedding is not ready, so the partition is semantically blind (#618)",
		slog.Bool("semantic_edges_applied", false))
}

func isProducerWideEmbeddingFault(err error) bool {
	if isEmbeddingIndexNotReady(err) || natsclient.IsNoResponders(err) {
		return true
	}
	var ce *errs.ClassifiedError
	return errors.As(err, &ce) && ce.Class == errs.ErrorFatal
}

type SemanticEdgesConfig struct {
	EnableSemanticEdges         bool    `json:"enable_semantic_edges,omitempty" schema:"type:bool,description:Enable semantic co-location (mutual-kNN) virtual edges in community detection (default false; enabling also rebalances the structural edge caps so the tier competes)"`
	SemanticSimilarityThreshold float64 `json:"semantic_similarity_threshold,omitempty" schema:"type:number,description:Minimum cosine similarity for a candidate to count toward an entity's top-k semantic neighbors (starting value 0.75)"`
	SemanticMaxNeighbors        int     `json:"semantic_max_neighbors,omitempty" schema:"type:int,description:Mutual-kNN k — per-direction top-k candidate set size; bounds per-entity semantic degree (starting value 8)"`
	SemanticEdgeWeight          float64 `json:"semantic_edge_weight,omitempty" schema:"type:number,description:Weight of a synthesized mutual-kNN semantic edge (starting value 0.9; below explicit 1.0, above the rebalanced structural tiers)"`
}

func (m *clusteringMetrics) addSemanticEdgeQueries(n int) {
	if n <= 0 {
		return
	}
	m.semanticEdgeSimilarQueries.Add(float64(n))
}

func (c *Config) DetectionInterval() time.Duration {
	return c.detectionInterval
}

func (c *Component) latchGraphStatePoison(err error) bool {
	var contractErr *graph.StateContractError
	if !errors.As(err, &contractErr) {
		return false
	}
	if c.graphStatePoison.CompareAndSwap(nil, contractErr) {
		c.logger.Error("authoritative graph state requires reset; clustering outputs are blocked",
			slog.String("code", graph.ErrorCodeGraphStateResetRequired),
			slog.String("reason", string(contractErr.Reason)))
	}
	return true
}

func (c *Component) evaluateSemanticAxis(embWatcher *readiness.Watcher) (active bool, embeddingRevision uint64) {
	if !c.config.semanticEdges.enabled || embWatcher == nil {
		return false, 0
	}
	reading := embWatcher.Read()
	return semanticActiveFromReading(reading), reading.Status.IndexedRevision
}

func (c *Component) waitForDependencies(ctx context.Context) error {
	watcherCfg := resource.DefaultConfig()
	watcherCfg.StartupAttempts = c.config.StartupAttempts
	watcherCfg.StartupInterval = time.Duration(c.config.StartupInterval) * time.Millisecond
	watcherCfg.Logger = c.logger

	// Wait for ENTITY_STATES bucket
	if err := c.waitForBucket(ctx, graph.BucketEntityStates, watcherCfg); err != nil {
		return err
	}
	entityBucket, err := graph.OpenCatalogReader(ctx, c.natsClient, graph.BucketEntityStates)
	if err != nil {
		return errs.Wrap(err, "Component", "waitForBucket", fmt.Sprintf("get %s bucket", graph.BucketEntityStates))
	}
	c.entityBucket = entityBucket

	// Wait for OUTGOING_INDEX bucket
	if err := c.waitForBucket(ctx, graph.BucketOutgoingIndex, watcherCfg); err != nil {
		return err
	}
	outgoingBucket, err := graph.OpenCatalogReader(ctx, c.natsClient, graph.BucketOutgoingIndex)
	if err != nil {
		return errs.Wrap(err, "Component", "waitForBucket", fmt.Sprintf("get %s bucket", graph.BucketOutgoingIndex))
	}
	c.outgoingBucket = outgoingBucket

	// Wait for INCOMING_INDEX bucket
	if err := c.waitForBucket(ctx, graph.BucketIncomingIndex, watcherCfg); err != nil {
		return err
	}
	incomingBucket, err := graph.OpenCatalogReader(ctx, c.natsClient, graph.BucketIncomingIndex)
	if err != nil {
		return errs.Wrap(err, "Component", "waitForBucket", fmt.Sprintf("get %s bucket", graph.BucketIncomingIndex))
	}
	c.incomingBucket = incomingBucket

	return nil
}

func (p *kvProvider) GetNeighbors(ctx context.Context, entityID string, direction string) ([]string, error) {
	if err := semtypes.ValidateEntityID(entityID); err != nil {
		return nil, errs.WrapInvalid(errs.ErrInvalidConfig, "kvProvider", "GetNeighbors", "entityID is empty")
	}

	// "both" is the explicit-edge membership question the LPA hot loop asks
	// (computeNewLabel(X) fans out one GetNeighbors(X,"both") then a
	// GetEdgeWeight(X,·) per neighbor), so it is served from the per-cycle edge
	// cache: this call warms it and GetEdgeWeight reuses the same union set,
	// reading X's topology once per cycle instead of once per neighbor (gh#666).
	if direction == "both" {
		set, err := p.bothNeighborSet(ctx, entityID)
		if err != nil {
			return nil, err
		}
		result := make([]string, 0, len(set))
		for n := range set {
			result = append(result, n)
		}
		return result, nil
	}

	// Single-direction reads are not part of the LPA hot loop and are left uncached.
	neighbors := make(map[string]bool)

	// Get outgoing neighbors — unchanged format: single key, JSON array of {to_entity_id, predicate}
	if direction == "outgoing" {
		outgoing, err := p.getNeighborsFromBucket(ctx, p.outgoingBucket, entityID)
		if err != nil {
			return nil, errs.WrapTransient(err, "kvProvider", "GetNeighbors", "outgoing topology read")
		}
		for _, n := range outgoing {
			neighbors[n] = true
		}
	}

	// Get incoming neighbors — composite-key sharded format: prefix scan
	if direction == "incoming" {
		incoming, err := p.getIncomingNeighbors(ctx, entityID)
		if err != nil {
			return nil, errs.WrapTransient(err, "kvProvider", "GetNeighbors", "incoming topology read")
		}
		for _, n := range incoming {
			neighbors[n] = true
		}
	}

	result := make([]string, 0, len(neighbors))
	for n := range neighbors {
		result = append(result, n)
	}
	return result, nil
}

func (c *Component) startReviewWorker(ctx context.Context) error {
	// Create relationship applier for approved anomalies
	// Uses the mutation API to go through graph-ingest for proper indexing
	applier := inference.NewMutationRelationshipApplier(c.natsClient, c.logger)

	reviewClient := c.resolveReviewLLMClient()

	// Resolve the capability timeout into ReviewConfig.ReviewTimeout so the
	// inner ctx.WithTimeout that wraps each review LLM call respects the
	// model-registry config. AnomalyConfig.Review.ReviewTimeout becomes the
	// fall-through default — endpoint.request_timeout > capability.timeout >
	// AnomalyConfig.Review.ReviewTimeout. Operators previously had to set
	// the inference-config knob; now anomaly_review.timeout in the model
	// registry suffices.
	reviewConfig := c.config.AnomalyConfig.Review
	if c.modelRegistry != nil && c.modelRegistry.GetCapability(model.CapabilityAnomalyReview) != nil {
		reviewConfig.ReviewTimeout = model.ResolveCapabilityTimeout(c.modelRegistry, model.CapabilityAnomalyReview, reviewConfig.ReviewTimeout, c.logger)
	}

	// Create review worker - reviewClient may be nil for human-only mode
	reviewWorker, err := inference.NewReviewWorker(&inference.ReviewWorkerConfig{
		AnomalyBucket: c.anomalyBucket,
		Storage:       c.anomalyStorage,
		LLMClient:     reviewClient,
		Applier:       applier,
		Config:        reviewConfig,
		Logger:        c.logger,
	})
	if err != nil {
		return errs.Wrap(err, "Component", "startReviewWorker", "create review worker")
	}
	c.reviewWorker = reviewWorker

	// Start the worker
	if err := c.reviewWorker.Start(ctx); err != nil {
		c.reviewWorker = nil
		return errs.Wrap(err, "Component", "startReviewWorker", "start review worker")
	}

	c.logger.Info("review worker started",
		slog.Int("workers", c.config.AnomalyConfig.Review.Workers),
		slog.Bool("llm_enabled", reviewClient != nil),
		slog.Bool("llm_dedicated", c.reviewLLMClient != nil),
		slog.Float64("auto_approve_threshold", c.config.AnomalyConfig.Review.AutoApproveThreshold),
		slog.Float64("auto_reject_threshold", c.config.AnomalyConfig.Review.AutoRejectThreshold))

	return nil
}

type kvProvider struct {
	entityBucket   entityBucketReader
	outgoingBucket outgoingBucketReader
	incomingBucket incomingBucketReader
	logger         *slog.Logger

	// explicitNeighbors memoizes each entity's "both"-direction explicit neighbor
	// set (outgoing ∪ incoming) for ONE detection cycle (gh#665/#666).
	// GetNeighbors("both") warms it and GetEdgeWeight reuses it, so
	// computeNewLabel(X) — which fans out one GetNeighbors(X,"both") then a
	// GetEdgeWeight(X,·) per neighbor — reads X's topology ONCE per cycle instead of
	// once per neighbor. ResetEdgeCache clears it at each cycle boundary because the
	// explicit topology changes as entities update between cycles; within a cycle
	// the snapshot is stable, which also gives every lookup a consistent graph view.
	//
	// TODAY there is a single accessor: the detection goroutine runs DetectCommunities
	// (LPA) then the structural pass sequentially, and the EnhancementWorker never
	// calls a topology method on the provider (it reads via its own querier). The
	// edgeCacheMu RWMutex is therefore DEFENSIVE, not resolving live contention.
	//
	// LATENT B3 HAZARD (comment-only, no reader exists yet): bothNeighborSet computes
	// a miss OUTSIDE the lock, then inserts under the lock with an absence-only
	// double-check. If a genuinely concurrent reader is ever wired (e.g. a B3
	// enhancement path), a ResetEdgeCache landing between compute-and-insert could
	// seed the fresh cycle's map with a prior-cycle snapshot for that one entity. A
	// real concurrent reader will need a cycle-generation stamp (or recompute under
	// the lock) — same class as the §7 B3 concurrency note; do NOT add it until a
	// reader exists.
	edgeCacheMu       sync.RWMutex
	explicitNeighbors map[string]map[string]bool
}

func (c *Component) initQuerySimilarityFinder() *querySimilarityFinder {
	if c.natsClient == nil {
		c.logger.Warn("NATS client not available, semantic gap detection disabled")
		return nil
	}

	finder := newQuerySimilarityFinder(c.natsClient, c.logger)
	c.logger.Info("query similarity finder initialized",
		slog.String("subject", similarQuerySubject))

	return finder
}

func (p *kvProvider) bothNeighborSet(ctx context.Context, entityID string) (map[string]bool, error) {
	p.edgeCacheMu.RLock()
	set, ok := p.explicitNeighbors[entityID]
	p.edgeCacheMu.RUnlock()
	if ok {
		return set, nil
	}

	computed, err := p.computeBothNeighborSet(ctx, entityID)
	if err != nil {
		return nil, err
	}

	p.edgeCacheMu.Lock()
	if existing, ok := p.explicitNeighbors[entityID]; ok {
		set = existing // another goroutine won the race — keep the shared snapshot
	} else {
		p.explicitNeighbors[entityID] = computed
		set = computed
	}
	p.edgeCacheMu.Unlock()
	return set, nil
}

func newKVProvider(
	entityBucket entityBucketReader,
	outgoingBucket outgoingBucketReader,
	incomingBucket incomingBucketReader,
	logger *slog.Logger,
) *kvProvider {
	return &kvProvider{
		entityBucket:      entityBucket,
		outgoingBucket:    outgoingBucket,
		incomingBucket:    incomingBucket,
		logger:            logger,
		explicitNeighbors: make(map[string]map[string]bool),
	}
}

func isRecognizedEmbeddingMiss(err error) bool {
	var ce *errs.ClassifiedError
	return errors.As(err, &ce) && ce.Code == graph.ErrorCodeEmbeddingUnavailable
}

func (c *Component) cleanup(ctx context.Context, retryable bool) error {
	var cleanupErr error
	unresolved := c.querySubscriptions[:0]
	for _, sub := range c.querySubscriptions {
		if sub == nil {
			continue
		}
		if err := sub.Drain(ctx); err != nil {
			cleanupErr = errors.Join(cleanupErr, err)
			unresolved = append(unresolved, sub)
		}
	}
	if retryable {
		c.querySubscriptions = unresolved
	} else {
		c.querySubscriptions = nil
	}
	if c.cancel != nil {
		c.cancel()
	}
	if c.runtimeDone != nil {
		select {
		case <-c.runtimeDone:
			if retryable {
				c.runtimeDone = nil
				c.cancel = nil
			}
		case <-ctx.Done():
			cleanupErr = errors.Join(cleanupErr, ctx.Err())
		}
	}
	if c.reviewWorker != nil {
		if err := c.reviewWorker.Stop(); err != nil {
			cleanupErr = errors.Join(cleanupErr, err)
		} else if retryable {
			c.reviewWorker = nil
		}
	}
	if c.enhancementWorker != nil {
		if err := c.enhancementWorker.Stop(); err != nil {
			cleanupErr = errors.Join(cleanupErr, err)
		} else if retryable {
			c.enhancementWorker = nil
		}
	}
	if c.llmClient != nil {
		if err := c.llmClient.Close(); err != nil {
			cleanupErr = errors.Join(cleanupErr, err)
		} else if retryable {
			c.llmClient = nil
		}
	}
	if c.reviewLLMClient != nil {
		if err := c.reviewLLMClient.Close(); err != nil {
			cleanupErr = errors.Join(cleanupErr, err)
		} else if retryable {
			c.reviewLLMClient = nil
		}
	}
	if c.statusWatcher != nil {
		c.statusWatcher.Stop()
		if retryable {
			c.statusWatcher = nil
		}
	}
	if c.embeddingStatusWatcher != nil {
		c.embeddingStatusWatcher.Stop()
		if retryable {
			c.embeddingStatusWatcher = nil
		}
	}
	return cleanupErr
}

func (c *Component) getEntityCommunity(ctx context.Context, entityID string, level int) (*clustering.Community, error) {
	if c.communityBucket == nil {
		return nil, errs.WrapFatal(errs.ErrInvalidConfig, "Component", "getEntityCommunity", "community bucket not initialized")
	}

	// Use indexed entity -> community mapping for O(1) lookup
	entityKey := fmt.Sprintf("entity.%d.%s", level, entityID)
	entry, err := c.communityBucket.Get(ctx, entityKey)
	if err != nil {
		if err == jetstream.ErrKeyNotFound {
			return nil, nil // Entity not in any community at this level
		}
		return nil, errs.WrapTransient(err, "Component", "getEntityCommunity", "get entity mapping")
	}

	communityID := string(entry.Value())

	// Fetch the community data
	communityKey := fmt.Sprintf("%d.%s", level, communityID)
	communityEntry, err := c.communityBucket.Get(ctx, communityKey)
	if err != nil {
		if err == jetstream.ErrKeyNotFound {
			return nil, nil // Mapping exists but community was deleted
		}
		return nil, errs.WrapTransient(err, "Component", "getEntityCommunity", "get community")
	}

	var community clustering.Community
	if err := json.Unmarshal(communityEntry.Value(), &community); err != nil {
		return nil, errs.Wrap(err, "Component", "getEntityCommunity", "community unmarshal")
	}

	return &community, nil
}

func (c *Config) Validate() error {
	if c.Ports == nil {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "ports configuration required")
	}
	if len(c.Ports.Inputs) == 0 {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "at least one input port required")
	}
	if len(c.Ports.Outputs) == 0 {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "at least one output port required")
	}

	// Validate COMMUNITY_INDEX output exists
	hasCommunityIndex := false
	for _, output := range c.Ports.Outputs {
		resolved, err := output.Resolve(component.DirectionOutput)
		if err != nil {
			return errs.WrapInvalid(err, "Config", "Validate", "resolve output port")
		}
		facts, err := resolved.Facts()
		if err != nil {
			return errs.WrapInvalid(err, "Config", "Validate", "project output port")
		}
		if facts.ResourceID() == "kv:STRUCTURAL_INDEX" {
			return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate",
				`STRUCTURAL_INDEX output was removed (ADR-090, BREAKING). Delete the output; anomaly detection computes structural prerequisites internally`)
		}
		if facts.ResourceID() == "kv:"+graph.BucketCommunityIndex {
			hasCommunityIndex = true
		}
	}
	if !hasCommunityIndex {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", fmt.Sprintf("%s output required", graph.BucketCommunityIndex))
	}
	if c.EnableAnomalyDetection {
		anomalyOutputs := 0
		for _, output := range c.Ports.Outputs {
			resolved, err := output.Resolve(component.DirectionOutput)
			if err != nil {
				return errs.WrapInvalid(err, "Config", "Validate", "resolve anomaly output port")
			}
			facts, err := resolved.Facts()
			if err != nil {
				return errs.WrapInvalid(err, "Config", "Validate", "project anomaly output port")
			}
			if output.Name == "anomaly_index" && facts.ResourceID() != "kv:"+graph.BucketAnomalyIndex {
				return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "anomaly_index must be a KV write to "+graph.BucketAnomalyIndex)
			}
			if facts.ResourceID() == "kv:"+graph.BucketAnomalyIndex {
				anomalyOutputs++
			}
		}
		if anomalyOutputs != 1 {
			return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", fmt.Sprintf("exactly one %s output required", graph.BucketAnomalyIndex))
		}
	}

	// Validate detection interval (parsed duration must be positive)
	if c.detectionInterval <= 0 {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "detection_interval must be greater than 0")
	}

	// Validate min community size
	if c.MinCommunitySize <= 0 {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "min_community_size must be greater than 0")
	}

	// Validate max iterations
	if c.MaxIterations <= 0 {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Config", "Validate", "max_iterations must be greater than 0")
	}

	// Validate anomaly config if anomaly detection is enabled
	if c.EnableAnomalyDetection && c.AnomalyConfig.Enabled {
		if err := c.AnomalyConfig.Validate(); err != nil {
			return errs.Wrap(err, "Config", "Validate", "anomaly_config")
		}
	}

	return nil
}

